<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import Icon from '../components/Icon.vue'
import { api } from '../api'
import { useChatStore } from '../stores/chat'
import { usePresenceStore } from '../stores/presence'

const chat = useChatStore(); const presence = usePresenceStore(); const query = ref(''); const draft = ref(''); const newGroup = ref(false); const groupName = ref(''); const memberIds = ref<string[]>([])
const filtered = computed(() => chat.conversations.filter(c => `${c.nombre || ''} ${c.interlocutor?.nombre || ''} ${c.ultimoMensaje || ''}`.toLocaleLowerCase('es').includes(query.value.toLocaleLowerCase('es'))))
function title(c: { tipo: string; nombre?: string | null; interlocutor?: { nombre: string } | null }) { return c.tipo === 'directa' ? c.interlocutor?.nombre || 'Conversación directa' : c.nombre || 'Grupo' }
function initials(name: string) { return name.split(/\s+/).filter(Boolean).slice(0,2).map(x => x[0]).join('').toUpperCase() }
async function send() { if (!draft.value.trim()) return; const value = draft.value; draft.value=''; try { await chat.sendMessage(value) } catch { draft.value=value } }
async function createGroup() { if (!groupName.value.trim()) return; await chat.createGroup(groupName.value, memberIds.value); newGroup.value=false; groupName.value=''; memberIds.value=[] }
onMounted(() => { void chat.load(); void presence.loadDirectory() })
</script>

<template>
  <main class="messages-page">
    <header class="page-header"><div><span class="eyebrow">Comunidad del laboratorio</span><h1>Mensajes</h1><p>Coordina el trabajo del equipo sin salir de FagoLab.</p></div><button class="btn btn-primary" @click="newGroup=true"><Icon name="plus" :size="16" /> Nuevo grupo</button></header>
    <section class="chat-layout card">
      <aside class="inbox"><div class="inbox-head"><label><Icon name="search" :size="16" /><input v-model="query" placeholder="Buscar conversaciones" /></label></div><button v-for="c in filtered" :key="c.id" class="inbox-row" :class="{ active: chat.selectedId===c.id }" @click="chat.select(c.id)"><span class="avatar">{{ initials(title(c)) }}</span><span><b>{{ title(c) }}</b><small>{{ c.ultimoMensaje || 'Sin mensajes todavía' }}</small></span><em v-if="c.noLeidos">{{ c.noLeidos }}</em></button><p v-if="!filtered.length" class="empty">No hay conversaciones aún.</p></aside>
      <section class="thread" v-if="chat.selected"><header><div><h2>{{ title(chat.selected) }}</h2><p>{{ chat.selected.tipo==='grupo' ? `${chat.selected.miembros?.length || 0} integrantes` : 'Chat privado' }}</p></div></header><div class="message-list"><article v-for="m in chat.messages" :key="m.id" :class="{ mine: m.autorId === undefined }"><b>{{ m.autorNombre || 'Sistema' }}</b><p>{{ m.cuerpo }}</p><footer><time>{{ new Date(m.createdAt).toLocaleString('es-MX',{dateStyle:'short',timeStyle:'short'}) }}</time><button v-for="reaction in m.reacciones" :key="reaction.emoji" @click="chat.react(m.id,reaction.emoji)">{{ reaction.emoji }} {{ reaction.usuarios.length }}</button><button @click="chat.react(m.id,'👍')">+</button></footer></article><p v-if="!chat.messages.length" class="empty">Sé quien inicia la conversación.</p></div><form class="message-form" @submit.prevent="send"><textarea v-model="draft" rows="3" placeholder="Escribe un mensaje…" @keydown.enter.exact.prevent="send"/><button class="btn btn-primary" :disabled="!draft.trim()" type="submit"><Icon name="arrow" :size="16" /> Enviar</button></form></section>
      <section v-else class="thread-empty"><Icon name="message" :size="35" /><h2>Elige una conversación</h2><p>O inicia un chat directo desde el panel de Personas.</p></section>
    </section>
    <div v-if="newGroup" class="modal-backdrop"><form class="modal card" @submit.prevent="createGroup"><header><h2>Crear grupo</h2><button type="button" @click="newGroup=false"><Icon name="close" :size="17" /></button></header><label>Nombre del grupo<input v-model="groupName" required maxlength="120" placeholder="Ej. Coordinación de muestreo" /></label><fieldset><legend>Integrantes</legend><label v-for="person in presence.people.filter(p=>!p.isCurrent)" :key="person.id" class="member"><input v-model="memberIds" type="checkbox" :value="person.id" /> {{ person.nombre }}</label></fieldset><footer><button type="button" class="btn" @click="newGroup=false">Cancelar</button><button class="btn btn-primary" :disabled="!groupName || !memberIds.length">Crear grupo</button></footer></form></div>
  </main>
</template>

<style scoped>
.messages-page{max-width:1280px;margin:auto;padding:30px}.page-header{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:22px}.eyebrow{color:var(--teal-600);font-size:.7rem;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.page-header h1{margin-top:5px;font-size:1.8rem}.page-header p{margin-top:5px;color:var(--muted)}.chat-layout{display:grid;grid-template-columns:320px minmax(0,1fr);height:min(700px,calc(100vh - 215px));min-height:520px;overflow:hidden}.inbox{overflow:auto;border-right:1px solid var(--line)}.inbox-head{padding:14px}.inbox-head label{display:flex;gap:7px;align-items:center;padding:9px;border:1px solid var(--line);border-radius:10px;color:var(--muted)}input,textarea{outline:0;border:0;background:transparent;color:var(--ink)}.inbox-head input{width:100%;font-size:.75rem}.inbox-row{display:flex;gap:10px;width:100%;padding:13px;border-top:1px solid var(--line-soft);text-align:left}.inbox-row:hover,.inbox-row.active{background:var(--teal-50)}.inbox-row>span:nth-child(2){display:grid;min-width:0;gap:3px}.inbox-row b,.inbox-row small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.inbox-row b{font-size:.78rem}.inbox-row small{color:var(--muted);font-size:.65rem}.avatar{display:grid;place-items:center;flex:none;width:37px;height:37px;border-radius:12px;color:#fff;background:linear-gradient(135deg,var(--teal),var(--blue));font-size:.65rem;font-weight:900}.inbox-row em{display:grid;place-items:center;align-self:center;margin-left:auto;min-width:19px;height:19px;border-radius:50%;color:#fff;background:var(--teal);font-size:.6rem;font-style:normal}.thread{display:flex;min-width:0;flex-direction:column}.thread>header{padding:17px 20px;border-bottom:1px solid var(--line)}.thread h2{font-size:.95rem}.thread header p{margin-top:3px;color:var(--muted);font-size:.68rem}.message-list{display:flex;flex:1;flex-direction:column;gap:10px;overflow:auto;padding:20px}.message-list article{align-self:flex-start;max-width:75%;padding:10px 12px;border-radius:13px 13px 13px 2px;background:var(--line-soft)}.message-list article.mine{align-self:flex-end;border-radius:13px 13px 2px;background:var(--teal-50)}article b{font-size:.65rem}article p{margin:4px 0;white-space:pre-wrap;font-size:.78rem;line-height:1.45}article footer{display:flex;align-items:center;gap:4px;color:var(--muted);font-size:.58rem}article footer button{padding:1px 4px;border-radius:6px;background:var(--panel);font-size:.58rem}.message-form{display:flex;gap:10px;padding:14px;border-top:1px solid var(--line)}.message-form textarea{flex:1;resize:none;padding:9px;border:1px solid var(--line);border-radius:10px;font-size:.78rem}.thread-empty,.empty{display:grid;place-items:center;align-content:center;gap:8px;padding:30px;color:var(--muted);text-align:center}.thread-empty h2{color:var(--ink);font-size:1rem}.modal-backdrop{position:fixed;inset:0;z-index:100;display:grid;place-items:center;padding:18px;background:#10273a66}.modal{display:grid;gap:16px;width:min(480px,100%);padding:22px}.modal header,.modal footer{display:flex;align-items:center;justify-content:space-between}.modal label{display:grid;gap:6px;font-size:.76rem;font-weight:800}.modal label>input{padding:10px;border:1px solid var(--line);border-radius:9px}.modal fieldset{display:grid;gap:6px;max-height:240px;overflow:auto;border:1px solid var(--line);border-radius:10px}.modal .member{display:block;font-weight:500}@media(max-width:760px){.messages-page{padding:18px}.chat-layout{grid-template-columns:1fr;height:auto}.inbox{max-height:250px;border-right:0;border-bottom:1px solid var(--line)}.thread{min-height:460px}.page-header{align-items:start;flex-direction:column}}
</style>
